    pub(super) fn parent(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        parent: Option<Value>,
        append: bool,
    ) -> Result<bool, Error> {
        if scene.owner != self.registry {
            return Ok(false);
        }
        let function = vm.rooted(if append { self.append } else { self.set_parent })?;
        Ok(vm.call(
            function,
            &[Value::Number(scene.id as f64), parent.unwrap_or(Value::Nil)],
        )?[0]
            == Value::Boolean(true))
    }
