/// Execute the actual production draw traversal, exposing capture errors before
/// the application wrapper reports them. Restore its callback flag on all exits.
pub fn draw_legacy_actor_scene(lua: &mlua::Lua, live: bool) -> mlua::Result<()> {
    let root: mlua::Table = lua.globals().get("root")?;
    let prior = lua
        .globals()
        .raw_get::<mlua::Value>("__songlua_draw_callback_active")?;
    lua.globals()
        .raw_set("__songlua_draw_callback_active", true)?;
    let result = if live {
        crate::draw_capture::run_live(lua, &root)
    } else {
        crate::draw_capture::run(lua, &root)
    };
    lua.globals()
        .raw_set("__songlua_draw_callback_active", prior)?;
    result
}

pub fn take_legacy_actor_draw_frames(
    lua: &mlua::Lua,
    sources: &[(&str, crate::SongLuaDrawSource)],
) -> Result<Vec<(usize, crate::SongLuaDrawFrame)>, String> {
    let mut bindings = rustc_hash::FxHashMap::default();
    for &(name, source) in sources {
        let actor: mlua::Table = lua.globals().get(name).map_err(|error| error.to_string())?;
        bindings.insert(actor.to_pointer() as usize, source);
    }
    let Some(capture) = lua.remove_app_data::<crate::draw_commands::Capture>() else {
        return Ok(Vec::new());
    };
    crate::draw_commands::convert(capture.frames, &capture.labels, &bindings)
}

